<script setup lang="ts">defineProps<{ values: { velvetThickness: number; safetyMargin: number; shrinkCompensation: number } }>(); const emit = defineEmits<{ update: [key: 'velvetThickness' | 'safetyMargin' | 'shrinkCompensation', value: number] }>();</script>
<template><section class="control-group"><h3>PLA & velvet tolerances</h3><label>Velvet thickness <output>{{ values.velvetThickness.toFixed(2) }} mm</output></label><Slider :model-value="values.velvetThickness" :min="0" :max="2" :step="0.1" @update:model-value="v => emit('update','velvetThickness',Number(v))"/><label>Safety margin <output>{{ values.safetyMargin.toFixed(2) }} mm</output></label><Slider :model-value="values.safetyMargin" :min="0" :max="1" :step="0.1" @update:model-value="v => emit('update','safetyMargin',Number(v))"/><label>Shrink compensation <output>{{ values.shrinkCompensation.toFixed(3) }}</output></label><Slider :model-value="values.shrinkCompensation" :min="0.98" :max="1.03" :step="0.001" @update:model-value="v => emit('update','shrinkCompensation',Number(v))"/></section></template>
